use nepl3_core::{budget::*,schema::SchemaRegistry,source::{SourceAdmission,SourceStore},value::NdfValue};
use nepl3_markup::{html::*,portable};use nepl3_wire::foundation::FoundationCodec;
fn b()->Budget{Budget::new(Limits{work:10000000,allocation_units:10000000,output_bytes:1000000,nodes:100000,depth:1000,..Limits::default()})}
fn err(x:impl core::fmt::Debug)->String{format!("{x:?}")}
fn req(source:&str,target:&str,fragment:Option<&str>)->HtmlRequest{HtmlRequest{slot:HtmlSlot::Phrasing,policy:HtmlPolicy{classes:vec![]},fragment:HtmlFragment{root:0,nodes:vec![HtmlNode::Element{tag:HtmlTag::A,attributes:vec![HtmlAttribute::Href{value:HtmlHref::BetweenArtifacts{source:source.into(),target:target.into(),fragment:fragment.map(Into::into)}}],children:vec![1]},HtmlNode::Text{text:"next".into()}]}}}
fn render(v:&HtmlRequest,b:&mut Budget)->Result<String,HtmlError>{serialize(&validate(&v.fragment,v.slot,&v.policy,b)?,b)}
fn route(v:&mut NdfValue)->&mut nepl3_core::value::Variant{let NdfValue::Record(r)=v else{panic!()};let NdfValue::Record(f)=&mut r.fields[0]else{panic!()};let NdfValue::List(ns)=&mut f.fields[1]else{panic!()};let NdfValue::Variant(e)=&mut ns[0]else{panic!()};let NdfValue::List(a)=&mut e.fields[1]else{panic!()};let NdfValue::Variant(h)=&mut a[0]else{panic!()};let NdfValue::Variant(route)=&mut h.fields[0]else{panic!()};route}
fn registry()->Result<SchemaRegistry,String>{let mut r=SchemaRegistry::default();for d in [nepl3_core::schema::foundation::descriptor(&mut b()),nepl3_markup::schema::descriptor(&mut b())]{let d=d.map_err(err)?;r.register(d.reference(&mut b()).map_err(err)?,d,&mut b()).map_err(err)?;}r.finalize(&mut b()).map_err(err)?;Ok(r)}
fn main()->Result<(),String>{
let paths=["index.html","a","a/b","a/b/c.html","a/bb/file.html","a/b/c/d.html","A/B_C-1.html",".hidden/index.html","a./b..html","a/b/index.html","docs/reference/x.html","docs/a/index.html","docs/ab/index.html",".../file"];
let r=registry()?;let empty=SourceStore::default();let mut count=0;
for source in paths{for target in paths{for fragment in [None,Some("section-2")]{let v=req(source,target,fragment);let original=v.clone();let html=render(&v,&mut b()).map_err(err)?;let href=html.strip_prefix("<a href=\"").unwrap().split('"').next().unwrap();println!("ROUTE\t{source}\t{target}\t{}\t{href}",fragment.unwrap_or(""));
 let bytes={let mut admission=SourceAdmission::default();let mut c=FoundationCodec::new(&r,&empty,&mut admission).map_err(err)?;let mut value=portable::to_value(&v,&r,&mut c,&mut b()).map_err(err)?;let tag=route(&mut value);assert_eq!(tag.variant,"BetweenArtifacts");assert_eq!(tag.fields[0],NdfValue::Text(source.into()));assert_eq!(tag.fields[1],NdfValue::Text(target.into()));nepl3_wire::encode(&value,&mut b()).map_err(err)?};
 let mut admission=SourceAdmission::default();let mut c=FoundationCodec::new(&r,&empty,&mut admission).map_err(err)?;let restored=portable::from_value(&nepl3_wire::decode(&bytes,&mut b()).map_err(err)?,&r,&mut c,&mut b()).map_err(err)?;assert_eq!(restored,v);assert_eq!(render(&restored,&mut b()).map_err(err)?,html);assert_eq!(v,original);count+=1;
}}}
let valid=req("docs/a/index.html","docs/b/topic.html",Some("section-2"));let mut admission=SourceAdmission::default();let mut c=FoundationCodec::new(&r,&empty,&mut admission).map_err(err)?;let raw=portable::to_value(&valid,&r,&mut c,&mut b()).map_err(err)?;
let invalid=["","/x","//host/x","a/","a//b",".","..","../x","a/./b","a/../b","C:/x","a:b","%2e%2e/x","a%2fb","a\\b","a?x","a#x","a b","a\t","a\n","a\0b","\u{65e5}/a","a~b"];
for path in invalid{for field in 0..2{let v=if field==0{req(path,"x",None)}else{req("x",path,None)};assert!(render(&v,&mut b()).is_err(),"{path:?}");let mut bad=raw.clone();route(&mut bad).fields[field]=NdfValue::Text(path.into());let packet=nepl3_wire::encode(&bad,&mut b()).map_err(err)?;let fresh=nepl3_wire::decode(&packet,&mut b()).map_err(err)?;assert!(portable::from_value(&fresh,&r,&mut c,&mut b()).is_err());}}
for fragment in ["","UPPER","2start","a_b","a/b","a#b","a?b","a%20b","a b","\u{65e5}"]{assert!(render(&req("index.html","other.html",Some(fragment)),&mut b()).is_err());}
// Raw declarations do not assert the actual current shell or destination existence.
let ghost=req("elsewhere/wrong-source.html","missing/no-file.html",Some("no-such-id"));assert!(render(&ghost,&mut b()).is_ok());let mut direct=ghost.clone();if let HtmlNode::Element{attributes,..}=&mut direct.fragment.nodes[0]{attributes[0]=HtmlAttribute::Href{value:HtmlHref::Fragment{id:"no-such-id".into()}};}assert!(matches!(render(&direct,&mut b()),Err(HtmlError::MissingFragment(_))));
let mut used=b();let expected=render(&valid,&mut used).map_err(err)?;let u=used.usage();let mut stops=0;let mut ok=0;
for (resource,needed,reason)in [(0,u.work,StopReason::WorkLimit),(1,u.allocation_units,StopReason::AllocationLimit),(2,u.output_bytes,StopReason::OutputLimit),(3,u.nodes,StopReason::NodeLimit),(4,u.depth,StopReason::DepthLimit)]{let mut caps=(0..=32).map(|i|needed*i/32).collect::<Vec<_>>();caps.extend([needed.saturating_sub(1),needed,needed+1]);caps.sort();caps.dedup();for cap in caps{let mut l=b().limits();match resource{0=>l.work=cap,1=>l.allocation_units=cap,2=>l.output_bytes=cap,3=>l.nodes=cap,_=>l.depth=cap};let mut bb=Budget::new(l);match render(&valid,&mut bb){Ok(s)=>{ok+=1;assert_eq!(s,expected);},Err(e)=>{stops+=1;assert_eq!(e,HtmlError::Stopped(reason));assert_eq!(bb.poll(),Err(reason));}}}}
let mut cancel=b();cancel.cancel();assert_eq!(render(&valid,&mut cancel),Err(HtmlError::Stopped(StopReason::Cancelled)));println!("PASS routes={count} invalid_paths={} sampled_stops={stops} successes={ok} input_preserved",invalid.len()*2);Ok(())}
